const data = msg.payload;

const fields = {
    temperature: Number(data.temperature),
    humidity: Number(data.humidity),
    moisture: Number(data.moisture),
    water_level: Number(data.water_level),
    light: Number(data.light),
    tds: Number(data.tds),

    pump: Number(data.pump),
    mist: Number(data.mist),
    led: Number(data.led),
    fan: Number(data.fan)
};

const tags = {
    device: data.device
};

msg.payload = [
    fields,
    tags
];

return msg;

const data = msg.payload;
const originMs = Date.parse(data?.origin_utc);
if (!data?.device || !Number.isFinite(originMs) ||
    !Array.isArray(data.model_forecasts) || data.model_forecasts.length === 0) {
    node.error("Missing model_forecasts or invalid origin; restart the updated Python service", msg);
    return null;
}

const points = [];
for (const forecast of data.model_forecasts) {
    const targetMs = Date.parse(forecast.target_time_utc);
    if (!["5m", "10m", "15m"].includes(forecast.horizon) ||
        !["persistence", "random_forest", "gradient_boosting"].includes(forecast.model) ||
        typeof forecast.moisture !== "number" || !Number.isFinite(forecast.moisture) ||
        !Number.isFinite(targetMs)) {
        node.error("Invalid model forecast", msg);
        return null;
    }
    points.push({
        measurement: "moisture_forecast",
        fields: {
            predicted_moisture: forecast.moisture,
            origin_epoch_ms: originMs
        },
        tags: {
            device: String(data.device),
            horizon: forecast.horizon,
            model: forecast.model
        },
        timestamp: new Date(targetMs)
    });
}
msg.payload = points;
return msg;

const data = msg.payload;

if (!data?.device || !data?.forecasts) {
    node.error("Invalid prediction payload", msg);
    return null;
}

const originMs = Date.parse(data.origin_utc);

if (!Number.isFinite(originMs)) {
    node.error("Invalid forecast origin timestamp", msg);
    return null;
}

const points = [];

for (const horizon of ["5m", "10m", "15m"]) {
    const forecast = data.forecasts[horizon];
    const moisture = forecast?.moisture;
    const targetMs = Date.parse(forecast?.target_time_utc);

    if (
        typeof moisture !== "number" ||
        !Number.isFinite(moisture) ||
        !Number.isFinite(targetMs)
    ) {
        node.error(`Invalid forecast for ${horizon}`, msg);
        return null;
    }

    const modelKey = horizon.replace("m", "");

    points.push({
        measurement: "moisture_forecast",

        fields: {
            predicted_moisture: moisture,
            origin_epoch_ms: originMs
        },

        tags: {
            device: String(data.device),
            horizon: horizon,
            model: data.selected_models?.[modelKey] ?? "unknown"
        },

        // Store at the time being predicted.
        timestamp: new Date(targetMs)
    });
}

msg.payload = points;
return msg;

const MODEL = "gradient_boosting";
const HORIZON = "10m";
const THRESHOLD = 60;       // Existing firmware threshold; validate experimentally.
const UPPER_LIMIT = 70;     // Provisional guard against watering already-wet soil.
const MAX_ORIGIN_AGE_MS = 90000;
const data = msg.payload;
const now = Date.now();

function finish(decision, reason, forecast) {
    msg.topic = "smartplant/policy/preview";
    msg.payload = {
        device: data && data.device,
        mode: "preview",
        model: MODEL,
        horizon: HORIZON,
        decision: decision,
        reason: reason,
        threshold: THRESHOLD,
        upper_moisture_limit: UPPER_LIMIT,
        current_moisture: data && data.current_minute_moisture,
        predicted_moisture: forecast ? forecast.moisture : null,
        origin_utc: data && data.origin_utc,
        target_time_utc: forecast ? forecast.target_time_utc : null,
        evaluated_at_utc: new Date(now).toISOString(),
        actuator_command_sent: false
    };
    node.status({fill: decision === "would_water" ? "yellow" :
                       decision === "reject" ? "red" : "green",
                 shape: "dot", text: decision + ": " + reason});
    return msg;
}

if (!data || data.device !== "esp32-01" || !Array.isArray(data.model_forecasts)) {
    return finish("reject", "invalid_payload_or_device");
}
const matches = data.model_forecasts.filter(function (f) {
    return f && f.model === MODEL && f.horizon === HORIZON;
});
if (matches.length !== 1) {
    return finish("reject", "missing_or_duplicate_gradient_forecast");
}
const forecast = matches[0];
const origin = Date.parse(data.origin_utc);
const target = Date.parse(forecast.target_time_utc);
if (!Number.isFinite(origin) || now - origin > MAX_ORIGIN_AGE_MS || origin > now) {
    return finish("reject", "stale_or_invalid_origin", forecast);
}
if (!Number.isFinite(target) || target - origin !== 10 * 60000) {
    return finish("reject", "invalid_target_time", forecast);
}
const current = data.current_minute_moisture;
const predicted = forecast.moisture;
if (typeof current !== "number" || !Number.isFinite(current) || current < 0 || current > 100 ||
    typeof predicted !== "number" || !Number.isFinite(predicted) || predicted < 0 || predicted > 100) {
    return finish("reject", "invalid_moisture", forecast);
}
if (current >= UPPER_LIMIT) {
    return finish("hold", "current_moisture_at_upper_limit", forecast);
}
if (predicted <= THRESHOLD) {
    return finish("would_water", "forecast_at_or_below_threshold", forecast);
}
return finish("hold", "forecast_above_threshold", forecast);

// One Function node, TWO outputs: 1 -> MQTT out, 2 -> Debug.
// Inputs: policy-preview messages AND parsed status/control messages.
// Start in observation mode. Change to true only after firmware upload/testing.
const ENABLE_COMMANDS = true;
const STATUS_TOPIC = "/smartplant/esp32-01/status/control";
const COMMAND_TOPIC = "/smartplant/esp32-01/control/pump";
const now = Date.now();
let data = msg.payload;

if (msg.topic === STATUS_TOPIC) {
    if (msg.retain) return [null, {payload: {result: "blocked", reason: "retained_status"}}];
    // Accept either parsed objects or JSON text from MQTT/JSON nodes.
    // This avoids silently dropping a status that was stringified upstream.
    if (typeof Buffer !== "undefined" && Buffer.isBuffer(data)) data = data.toString("utf8");
    if (typeof data === "string") {
        try { data = JSON.parse(data); }
        catch (error) {
            return [null, {payload: {result: "blocked", reason: "invalid_status_json"}}];
        }
    }
    if (!data || typeof data !== "object" || Array.isArray(data) ||
        typeof data.session !== "string" || !data.session) {
        return [null, {payload: {result: "blocked", reason: "invalid_status_payload",
            payload_type: typeof data, expected: "object with non-empty session"}}];
    }
    context.set("pump_status", {received: now, data: data});
    return [null, {payload: {result: "status_cached", topic: msg.topic,
        mode: data.mode, predictive_ready: data.predictive_ready,
        received_at_utc: new Date(now).toISOString()}}];
}

function blocked(reason) {
    return [null, {payload: {result: "blocked", reason: reason,
        evaluated_at_utc: new Date(now).toISOString()}}];
}
// A status-shaped object arriving under another topic cannot update the cache.
if (data && typeof data === "object" && typeof data.session === "string") {
    return [null, {payload: {result: "blocked", reason: "unexpected_status_topic",
        received_topic: msg.topic || "(missing)", expected_topic: STATUS_TOPIC}}];
}
if (!data || data.device !== "esp32-01" || data.mode !== "preview"
    || data.model !== "gradient_boosting" || data.horizon !== "10m"
    || data.decision !== "would_water") return blocked("no_qualifying_decision");
const origin = Date.parse(data.origin_utc);
const target = Date.parse(data.target_time_utc);
if (!Number.isFinite(origin) || origin > now || now - origin > 90000
    || target - origin !== 600000) return blocked("stale_or_invalid_forecast");
if (typeof data.predicted_moisture !== "number" || !Number.isFinite(data.predicted_moisture)
    || data.predicted_moisture < 0 || data.predicted_moisture > 60
    || typeof data.current_moisture !== "number" || !Number.isFinite(data.current_moisture)
    || data.current_moisture < 0 || data.current_moisture >= 70) return blocked("invalid_moisture");
const cached = context.get("pump_status");
if (!cached || now - cached.received > 15000 || cached.received > now) {
    return [null, {payload: {result: "blocked", reason: "waiting_for_fresh_esp32_status",
        cache_present: Boolean(cached), status_age_ms: cached ? now - cached.received : null,
        evaluated_at_utc: new Date(now).toISOString()}}];
}
const status = cached.data;
if (status.mode !== "predictive" || status.predictive_ready !== true
    || status.pump_on !== false || status.cooldown_remaining_ms !== 0)
    return blocked("esp32_not_ready");
if (!ENABLE_COMMANDS) return blocked("observation_only_commands_disabled");
const previous = context.get("last_pump_request");
if (previous && (origin <= previous.origin || now - previous.sent < 300000))
    return blocked("duplicate_or_local_cooldown");
const command = {
    command_id: status.session + "-" + origin,
    session: status.session,
    action: "pulse",
    duration_ms: 500,
    issued_at_epoch_ms: now,
    expires_at_epoch_ms: now + 15000,
    origin_epoch_ms: origin,
    model: "gradient_boosting",
    horizon: "10m",
    predicted_moisture: data.predicted_moisture
};
// Conservative: even a lost/rejected request starts the local cooldown.
// This is a request, NOT confirmation that watering occurred.
context.set("last_pump_request", {origin: origin, sent: now});
return [{topic: COMMAND_TOPIC, payload: JSON.stringify(command), qos: "0", retain: false},
    {payload: {result: "request_sent", command: command}}];

// Node-RED Function: branch from Gradient Boosting Policy Preview -> this -> influxdb batch.
// One output. Returns a NEW message; does not modify the control-policy message.
const data = msg.payload;
if (!data || data.mode !== "preview" ||
    !["would_water", "hold", "reject"].includes(data.decision) ||
    typeof data.reason !== "string") {
    node.error("Decision logger requires a policy-preview object", msg);
    return null;
}
const evaluated = Date.parse(data.evaluated_at_utc);
if (!Number.isFinite(evaluated)) {
    node.error("Decision has no valid evaluation time", msg);
    return null;
}
function finite(value) {
    return typeof value === "number" && Number.isFinite(value);
}
function display(value) {
    return finite(value) ? value.toFixed(2) : "unavailable";
}
const explanations = {
    forecast_at_or_below_threshold:
        "Forecast " + display(data.predicted_moisture) + "% <= threshold " +
        display(data.threshold) + "%; current minute-average " + display(data.current_moisture) +
        "% < upper limit " + display(data.upper_moisture_limit) +
        "%. Policy qualifies for a watering request; actuator checks are separate.",
    forecast_above_threshold:
        "Forecast " + display(data.predicted_moisture) + "% > threshold " +
        display(data.threshold) + "%. Policy holds watering.",
    current_moisture_at_upper_limit:
        "Current minute-average " + display(data.current_moisture) + "% >= upper limit " +
        display(data.upper_moisture_limit) + "%. Policy holds watering.",
    invalid_payload_or_device: "Payload is invalid or is not for the configured device.",
    missing_or_duplicate_gradient_forecast:
        "Exactly one Gradient Boosting forecast for the selected horizon is required.",
    stale_or_invalid_origin:
        "Forecast origin is invalid, in the future, or older than the policy's 90-second limit.",
    invalid_target_time: "Target time is invalid or is not exactly 10 minutes after origin.",
    invalid_moisture: "Current or predicted moisture is not a finite number in the range 0 to 100%."
};
const fields = {
    decision: data.decision,
    reason_code: data.reason,
    explanation: explanations[data.reason] || "Unrecognized policy reason: " + data.reason,
    explanation_type: "control_policy_rules",
    policy_version: "gradient_10m_v1",
    control_mode: "preview",
    // This records the POLICY stage; it does not describe later command delivery.
    actuator_command_sent_at_policy_stage: false
};
for (const name of ["current_moisture", "predicted_moisture", "threshold", "upper_moisture_limit"]) {
    if (finite(data[name])) fields[name] = data[name];
}
for (const pair of [["origin_utc", "origin_epoch_ms"], ["target_time_utc", "target_epoch_ms"]]) {
    const value = Date.parse(data[pair[0]]);
    if (Number.isFinite(value)) fields[pair[1]] = value;
}
// Numeric value for a Grafana State timeline or count queries.
fields.decision_code = {would_water: 1, hold: 0, reject: -1}[data.decision];
return {payload: [{
    measurement: "moisture_policy_decision",
    tags: {
        device: typeof data.device === "string" && data.device ? data.device : "unknown",
        model: data.model || "unknown",
        horizon: data.horizon || "unknown",
        stage: "policy"
    },
    fields: fields,
    // Decision time, NOT forecast target time: future actions have not happened yet.
    timestamp: new Date(evaluated)
}]};

// Allow real pump requests when ALL checks below pass.
// false = observation only; true = allow command transmission.
const ENABLE_COMMANDS = true;

// ESP32 publishes its current mode, readiness, and session here.
const STATUS_TOPIC = "/smartplant/esp32-01/status/control";

// Node-RED publishes pump requests here for the ESP32.
const COMMAND_TOPIC = "/smartplant/esp32-01/control/pump";

// Current time as milliseconds since the Unix epoch.
// The computer running Node-RED needs an accurate clock.
const now = Date.now();

// Incoming payload must already be a parsed JavaScript object.
const data = msg.payload;


// ── 1. Receive and cache ESP32 status ──────────────────────────

// This Function receives two kinds of messages:
// - ESP32 status messages
// - Decisions from Gradient Boosting Policy Preview
//
// Identify status messages by their MQTT topic.
if (msg.topic === STATUS_TOPIC) {

    // Ignore retained status delivered by the broker.
    // It may describe an old ESP32 session or operating condition.
    if (msg.retain) {
        return [
            null,
            {payload: {result: "blocked", reason: "retained_status"}}
        ];
    }

    // Require a non-empty session identifier from the ESP32.
    // The firmware changes its session after reconnect/mode changes.
    if (!data || typeof data.session !== "string" || !data.session) {
        return null;
    }

    // Save the latest status and its local receipt time.
    // Node context retains values between messages for this Function.
    context.set("pump_status", {
        received: now,
        data: data
    });

    // A status update only refreshes the cache.
    // It does not trigger a watering request.
    return null;
}


// ── 2. Helper for reporting blocked requests ───────────────────

function blocked(reason) {
    // First output: null → no MQTT command.
    // Second output: diagnostic object → Debug.
    return [
        null,
        {
            payload: {
                result: "blocked",
                reason: reason,
                evaluated_at_utc: new Date(now).toISOString()
            }
        }
    ];
}


// ── 3. Require the intended policy decision ────────────────────

// Accept only the expected device, model, horizon, and decision.
//
// "preview" describes the upstream policy message format.
// It is separate from the ESP32's operating mode, checked later.
//
// Any "hold" or "reject" decision stops here.
if (
    !data ||
    data.device !== "esp32-01" ||
    data.mode !== "preview" ||
    data.model !== "gradient_boosting" ||
    data.horizon !== "10m" ||
    data.decision !== "would_water"
) {
    return blocked("no_qualifying_decision");
}


// ── 4. Check forecast timestamps ──────────────────────────────

// Convert ISO timestamps into epoch milliseconds.
const origin = Date.parse(data.origin_utc);
const target = Date.parse(data.target_time_utc);

// Require:
// - A valid forecast origin.
// - Origin is not in the future.
// - Forecast origin is no more than 90 seconds old.
// - Target is exactly 10 minutes after origin.
//
// 90,000 ms = 90 seconds.
// 600,000 ms = 10 minutes.
if (
    !Number.isFinite(origin) ||
    origin > now ||
    now - origin > 90000 ||
    target - origin !== 600000
) {
    return blocked("stale_or_invalid_forecast");
}


// ── 5. Check moisture conditions independently ────────────────

// Recheck the numbers even though the preview policy checked them.
//
// Predicted moisture must be between 0% and 60%, inclusive.
// Current minute-average moisture must be between 0% and 70%,
// excluding 70%.
//
// The ESP32 also checks its own local sensor readings later.
if (
    typeof data.predicted_moisture !== "number" ||
    !Number.isFinite(data.predicted_moisture) ||
    data.predicted_moisture < 0 ||
    data.predicted_moisture > 60 ||
    typeof data.current_moisture !== "number" ||
    !Number.isFinite(data.current_moisture) ||
    data.current_moisture < 0 ||
    data.current_moisture >= 70
) {
    return blocked("invalid_moisture");
}


// ── 6. Require recent ESP32 status ─────────────────────────────

const cached = context.get("pump_status");

// Reject if no status has arrived, its receipt time is in the
// future, or it was received more than 15 seconds ago.
//
// This checks receipt age; it is not a sensor timestamp check.
if (
    !cached ||
    now - cached.received > 15000 ||
    cached.received > now
) {
    return blocked("waiting_for_fresh_esp32_status");
}

const status = cached.data;

// ESP32 must explicitly report:
// - Predictive operating mode.
// - Ready to accept a predictive request.
// - Pump is OFF.
// - No remaining cooldown.
//
// predictive_ready includes the firmware's readiness checks,
// such as clock, sensor conditions, and timer availability.
if (
    status.mode !== "predictive" ||
    status.predictive_ready !== true ||
    status.pump_on !== false ||
    status.cooldown_remaining_ms !== 0
) {
    return blocked("esp32_not_ready");
}


// ── 7. Check the command enable switch ─────────────────────────

// With commands disabled, diagnostics still run,
// but no pump request can leave output 1.
if (!ENABLE_COMMANDS) {
    return blocked("observation_only_commands_disabled");
}


// ── 8. Reject repeated forecasts and enforce local cooldown ───

const previous = context.get("last_pump_request");

// If a request was previously sent:
// - Do not reuse its forecast origin or an older origin.
// - Wait at least five minutes after that request.
//
// 300,000 ms = 5 minutes.
//
// This is Node-RED's additional cooldown.
// ESP32 independently enforces its own cooldown.
if (
    previous &&
    (
        origin <= previous.origin ||
        now - previous.sent < 300000
    )
) {
    return blocked("duplicate_or_local_cooldown");
}


// ── 9. Build the pump request ──────────────────────────────────

const command = {

    // Identifies this request using ESP32 session + forecast origin.
    command_id: status.session + "-" + origin,

    // Binds the request to the ESP32's current control session.
    session: status.session,

    // Request one bounded pulse, not continuous operation.
    action: "pulse",

    // Requested pump ON time: 500 milliseconds = 0.5 seconds.
    duration_ms: 500,

    // Time this request was created.
    issued_at_epoch_ms: now,

    // ESP32 must reject it after 15 seconds.
    // This expiry is separate from the 10-minute forecast horizon.
    expires_at_epoch_ms: now + 15000,

    // Original time from which the forecast was made.
    origin_epoch_ms: origin,

    // Record which prediction caused the request.
    model: "gradient_boosting",
    horizon: "10m",
    predicted_moisture: data.predicted_moisture
};


// ── 10. Record the request before sending ──────────────────────

// Start Node-RED's cooldown immediately.
//
// Even if MQTT delivery fails or ESP32 rejects the request,
// Node-RED still waits five minutes before another request.
// This deliberately avoids rapid retries.
context.set("last_pump_request", {
    origin: origin,
    sent: now
});


// ── 11. Send to the two Function outputs ───────────────────────

return [
    {
        // OUTPUT 1 → MQTT out
        topic: COMMAND_TOPIC,

        // Convert the command object into JSON text for MQTT.
        payload: JSON.stringify(command),

        // QoS 0: delivery is not guaranteed.
        qos: "0",

        // Do not store this actuator command as a retained message.
        retain: false
    },
    {
        // OUTPUT 2 → Debug
        payload: {
            result: "request_sent",
            command: command
        }
    }
];
